import{_ as t,H as a,f as i,i as l}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"加餐4 | 建模作业点评直播回放&获奖公示","description":"","frontmatter":{},"headers":[{"level":2,"title":"直播背景","slug":"直播背景","link":"#直播背景","children":[]},{"level":2,"title":"建模题目与参考答案","slug":"建模题目与参考答案","link":"#建模题目与参考答案","children":[{"level":3,"title":"建模题题干","slug":"建模题题干","link":"#建模题题干","children":[]},{"level":3,"title":"参考答案","slug":"参考答案","link":"#参考答案","children":[]}]},{"level":2,"title":"获奖信息公示","slug":"获奖信息公示","link":"#获奖信息公示","children":[]}],"relativePath":"手把手教你落地DDD/加餐4｜建模作业点评直播回放&获奖公示.md","filePath":"手把手教你落地DDD/加餐4｜建模作业点评直播回放&获奖公示.md","lastUpdated":1795557830000}'),n={name:"手把手教你落地DDD/加餐4｜建模作业点评直播回放&获奖公示.md"};function s(p,e,r,o,h,E){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="加餐4-建模作业点评直播回放-获奖公示" tabindex="-1">加餐4 | 建模作业点评直播回放&amp;获奖公示 <a class="header-anchor" href="#加餐4-建模作业点评直播回放-获奖公示" aria-label="Permalink to &quot;加餐4 | 建模作业点评直播回放&amp;获奖公示&quot;">​</a></h1><p>你好，我是小新，《手把手教你落地 DDD》专栏的编辑。</p><p>今天是一次特别加餐的内容，我想和你分享一下上建模作业的在线点评直播，这次直播和课程所讲的内容紧密相关。</p><h2 id="直播背景" tabindex="-1">直播背景 <a class="header-anchor" href="#直播背景" aria-label="Permalink to &quot;直播背景&quot;">​</a></h2><p>在领域驱动设计（DDD）里，很重要的一环就是学好领域建模。为了帮助同学们深入理解DDD 建模思路，提升实战技能，钟老师精心设计了一道建模题目。</p><p>截至 1 月 31 日，我们一共收到了 11 份作业。钟老师认真批阅后，并且把点评内容做了详细记录。借着这次作业的契机，还特别安排了线上直播和同学们交流互动。</p><p>在直播里，老师分享了敏捷的相关知识，结合建模作业给出了参考答案，并且在此基础上做了进一步扩展、延伸，之后还结合提交的作业做了逐一分析点评。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%258A%25A0%25E9%25A4%25904/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%258A%25A0%25E9%25A4%25904/1.png" alt=""></a></p><p>直播回放以及直播 PPT 如下，建议学完迭代一的同学先完成建模作业（题目见后面“建模题题干”），再参考直播讲解，学习效果会更好。</p><p>直播回放地址：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%258A%25A0%25E9%25A4%25904/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%258A%25A0%25E9%25A4%25904/2.jpeg" alt=""></a></p><p>直播 PPT 链接：</p><p><a href="https://pan.baidu.com/s/1BnW3Q2ZA4Dkz8o9Zf5pTSA" target="_blank" rel="noreferrer">https://pan.baidu.com/s/1BnW3Q2ZA4Dkz8o9Zf5pTSA</a> 提取码: wd29</p><h2 id="建模题目与参考答案" tabindex="-1">建模题目与参考答案 <a class="header-anchor" href="#建模题目与参考答案" aria-label="Permalink to &quot;建模题目与参考答案&quot;">​</a></h2><p>后面是活动的建模题目和钟老师提供的参考答案（进一步的延伸扩展，你可以通过直播回放学习）。</p><h3 id="建模题题干" tabindex="-1">建模题题干 <a class="header-anchor" href="#建模题题干" aria-label="Permalink to &quot;建模题题干&quot;">​</a></h3><p>假设你所在的公司想实施敏捷软件开发，委托你为公司开发一个敏捷项目管理软件。公司领导提出的需求是这样的：</p><ul><li><p>公司会开发很多款软件产品，每个产品有一个产品待办清单（product backlog）。</p></li><li><p>产品待办清单中的待办项是用户故事，由产品经理提供。</p></li><li><p>用户故事有一个文字性的描述，还有若干验收条件（Acceptance Criteria）。</p></li><li><p>产品经理可调整待办项的优先级。</p></li><li><p>每个用户故事要估算故事点。</p></li><li><p>每个迭代，项目经理把用户故事移入迭代待办清单（sprint backlog）。</p></li><li><p>每个迭代，由一个敏捷团队负责。</p></li><li><p>迭代待办清单所有故事点的和不能超过迭代容量。</p></li><li><p>每个用户故事由一个同事负责。</p></li><li><p>每个用户故事有 TODO、DOING、DONE 三种状态，由开发人员切换状态。请根据上面的场景，用你熟悉的工具绘制出系统的领域模型。然后把模型以图片的形式导出，贴在你喜欢的共享文档（例如腾讯文档、石墨文档等）。</p></li></ul><p>这道题假设你学习完了迭代一，并且了解敏捷软件开发过程。如果对“产品待办清单”“迭代待办清单”“用户故事”“验收条件”“故事点”“敏捷团队”等概念还不了解的话，可以去网上搜一下，这些都是敏捷的一些基本概念。</p><h3 id="参考答案" tabindex="-1">参考答案 <a class="header-anchor" href="#参考答案" aria-label="Permalink to &quot;参考答案&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%258A%25A0%25E9%25A4%25904/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%258A%25A0%25E9%25A4%25904/3.png" alt=""></a></p><h2 id="获奖信息公示" tabindex="-1">获奖信息公示 <a class="header-anchor" href="#获奖信息公示" aria-label="Permalink to &quot;获奖信息公示&quot;">​</a></h2><p>在 11 份作业中，老师评选了 4 份优秀作业，我们将寄出一份礼品作为鼓励。感谢所有参与的同学，因为你们的加入让这个专栏更加丰富多彩。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%258A%25A0%25E9%25A4%25904/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%258A%25A0%25E9%25A4%25904/4.png" alt=""></a></p><p>最后说点题外话。活动告一段落，学习和交流仍在继续。学完课程的迭代一之后，可以继续挑战这道建模题目，动手练习之后再来观看老师的直播回放。</p><p>学完迭代二、三，也欢迎你随时来回味，说不定你就会对建模实践产生新的思考。</p><p>欢迎你继续学习本课程，在留言区分享你的学习心得或提出问题。下节课，我们继续更新正文，继续陪伴“卷卷通”公司迎接新的挑战，学习 DDD 里更高阶的技能，敬请期待！</p>',27)])])}const A=t(n,[["render",s]]);export{c as __pageData,A as default};
